CREATE INDEX IF NOT EXISTS lab_producao_patient_recovery_idx ON public.lab_producao_feegow(paciente_id) WHERE paciente_id>0;
CREATE INDEX IF NOT EXISTS agendamentos_patient_recovery_idx ON public.agendamentos(paciente_id) WHERE paciente_id>0;
CREATE OR REPLACE VIEW public.lab_vw_pacientes_pendentes WITH(security_invoker=true) AS WITH ids AS MATERIALIZED (SELECT paciente_id FROM public.lab_producao_feegow WHERE paciente_id>0 UNION SELECT paciente_id FROM public.agendamentos WHERE paciente_id>0) SELECT i.paciente_id,p.paciente_id IS NULL sem_cadastro FROM ids i LEFT JOIN public.pacientes p ON p.paciente_id=i.paciente_id LEFT JOIN public.lab_paciente_sync_estado s ON s.paciente_id=i.paciente_id WHERE (p.paciente_id IS NULL OR coalesce(p.cadastro_sincronizado_em,p.updated_at)<now()-interval '60 days') AND (s.erro IS NULL OR s.tentado_em<now()-interval '1 day');